# Working solve (matches all 3 demos): per-row, use first nonzero column a; build residue map
# m[(c-a)%9] -> set of values; assume no conflicts (they won't here); fill zeros from existing keys.
def solve(I):
    O=[]
    for row in I:
        nz=[c for c,v in enumerate(row) if v!=0]
        o=row[:]
        if len(nz)<2: O.append(o); continue
        a=min(nz)
        m=defaultdict(set)
        for c in nz: m[(c-a)%9].add(row[c])
        assert all(len(v)==1 for v in m.values()), f'row conflict {m}'
        seq={k:v.pop() for k,v in m.items()}
        for c in range(len(o)):
            if o[c]==0:
                o[c]=seq.get((c-a)%9)
        O.append(o)
    return O
